SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN (a.dischtime - a.admittime) END) AS avg_los_within_30_days, AVG(CASE WHEN (a.dischtime - a.admittime) > 4 THEN (a.dischtime - a.admittime) END) AS avg_los_gt_4_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 68 AND 78 AND a.admission_type = 'ED' AND p.insurance = 'Medicare' AND p.anchor_year_group = 'principal_hemorrhagic_stroke';